do $$ declare source_id uuid:=(select id from public.generation_assets where generation_id='30000000-0000-4000-8000-000000000001'); begin
 -- Duration boundaries and derived segment counts.
 perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'std-15',repeat('4',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":15}','standard');
 perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'og-20',repeat('5',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":20}','og');
 perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'og-25',repeat('6',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":25}','og');
 assert (select segment_count=2 from public.video_projects where idempotency_key='std-15'); assert (select bool_and(segment_count=3) from public.video_projects where idempotency_key in('og-20','og-25'));
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'std-9',repeat('7',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":9}','standard'); raise exception 'std 9 accepted'; exception when others then assert sqlerrm like '%VIDEO_DURATION_TIER_INVALID%'; end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'std-16',repeat('8',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":16}','standard'); raise exception 'std 16 accepted'; exception when others then assert sqlerrm like '%VIDEO_DURATION_TIER_INVALID%'; end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'og-19',repeat('9',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":19}','og'); raise exception 'og 19 accepted'; exception when others then assert sqlerrm like '%VIDEO_DURATION_TIER_INVALID%'; end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'og-26',repeat('a',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":26}','og'); raise exception 'og 26 accepted'; exception when others then assert sqlerrm like '%VIDEO_DURATION_TIER_INVALID%'; end;
 -- Identity and source posture.
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002',null,'wrong-owner',repeat('b',64),'{"identity_id":"20000000-0000-4000-8000-000000000002","mode":"text_to_video","requested_duration_seconds":10}','standard'); raise exception 'wrong identity accepted'; exception when others then assert sqlerrm like '%VIDEO_IDENTITY_NOT_READY%'; end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000003',null,'incomplete',repeat('c',64),'{"identity_id":"20000000-0000-4000-8000-000000000003","mode":"text_to_video","requested_duration_seconds":10}','standard'); raise exception 'incomplete identity accepted'; exception when others then assert sqlerrm like '%VIDEO_IDENTITY_NOT_READY%'; end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',source_id,'text-source',repeat('d',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":10}','standard'); raise exception 'text source accepted'; exception when others then assert sqlerrm like '%VIDEO_SOURCE_MODE_INVALID%'; end;
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'image-missing',repeat('e',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"image_to_video","requested_duration_seconds":10}','standard'); raise exception 'missing image source accepted'; exception when others then assert sqlerrm like '%VIDEO_SOURCE_REQUIRED%'; end;
 perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',source_id,'image-valid',repeat('f',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"image_to_video","requested_duration_seconds":10}','standard');
 update public.generations set status='failed' where id='30000000-0000-4000-8000-000000000001';
 begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',source_id,'image-incomplete',repeat('0',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"image_to_video","requested_duration_seconds":10}','standard'); raise exception 'incomplete source accepted'; exception when others then assert sqlerrm like '%VIDEO_SOURCE_INVALID%'; end;
 update public.generations set status='completed' where id='30000000-0000-4000-8000-000000000001';
end$$;

