do $$ begin
 assert (select segment_count=2 and target_fps=30 and target_min_short_edge=1080 from public.video_projects where id=(select project_id from submitted));
 assert (select count(*)=1 from public.compute_jobs where workload='video' and request_payload->>'project_id'=(select project_id::text from submitted));
 assert (select count(*)=1 from public.compute_jobs where workload='stitch' and request_payload->>'project_id'=(select project_id::text from submitted));
 assert (select max_attempts=3 from public.compute_jobs where workload='video' and request_payload->>'project_id'=(select project_id::text from submitted));
 assert (select max_attempts=4 from public.compute_jobs where workload='stitch' and request_payload->>'project_id'=(select project_id::text from submitted));
 assert not exists(select 1 from public.claim_compute_job('stitch','worker'));
end$$;
-- Exercise normal authority, contiguous segment persistence, Stitch dependency, and canonical product.
update public.compute_jobs set state='running',attempt_count=1,lease_token='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',lease_expires_at=clock_timestamp()+interval '5 minutes',started_at=clock_timestamp()
 where id=(select video_job_id from public.video_projects where id=(select project_id from submitted));
insert into public.compute_job_attempts(job_id,ordinal,lease_token,worker_ref,lease_expires_at,started_at,provider_dispatch_intent_at,provider_dispatched_at,provider_operation_ref,actual_cost_micros,runtime_ms)
 select video_job_id,1,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','video-test',clock_timestamp()+interval '5 minutes',clock_timestamp(),clock_timestamp(),clock_timestamp(),'opaque-video-operation',0,5000 from public.video_projects where id=(select project_id from submitted);
do $$ declare v public.video_projects;a public.compute_job_attempts;assets jsonb;bad jsonb; begin
 select * into v from public.video_projects where id=(select project_id from submitted); select * into a from public.compute_job_attempts where job_id=v.video_job_id;
 assets:=jsonb_build_array(jsonb_build_object('ordinal',0,'bucket','video-private','object_key','creator-video-projects/'||v.id||'/segments/0/segment-0.mp4','mime_type','video/mp4','size_bytes',1000,'sha256',repeat('1',64)),jsonb_build_object('ordinal',1,'bucket','video-private','object_key','creator-video-projects/'||v.id||'/segments/1/segment-1.mp4','mime_type','video/mp4','size_bytes',1001,'sha256',repeat('2',64)));
 assert (public.video_compute_manifest(v.video_job_id,a.id,a.lease_token)->>'project_id')=v.id::text;
 begin perform public.video_compute_manifest(v.video_job_id,a.id,gen_random_uuid()); raise exception 'wrong manifest lease accepted'; exception when others then assert sqlerrm like '%VIDEO_MANIFEST_AUTHORITY_MISMATCH%'; end;
 begin perform public.finalize_video_compute_job(v.video_job_id,a.id,gen_random_uuid(),assets); raise exception 'wrong lease accepted'; exception when others then assert sqlerrm like '%VIDEO_FINALIZATION_AUTHORITY_MISMATCH%'; end;
 bad:=jsonb_set(assets,'{0,ordinal}','"0"'); begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,bad); raise exception 'string ordinal accepted'; exception when others then assert sqlerrm like '%VIDEO_SEGMENT_EVIDENCE_INVALID%'; end;
 bad:=jsonb_set(assets,'{0,size_bytes}','1.5'); begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,bad); raise exception 'fraction size accepted'; exception when others then assert sqlerrm like '%VIDEO_SEGMENT_EVIDENCE_INVALID%'; end;
 bad:=jsonb_set(assets,'{0,bucket}','123'); begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,bad); raise exception 'numeric bucket accepted'; exception when others then assert sqlerrm like '%VIDEO_SEGMENT_EVIDENCE_INVALID%'; end;
 bad:=jsonb_set(assets,'{0,mime_type}','"video/webm"'); begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,bad); raise exception 'webm accepted'; exception when others then assert sqlerrm like '%VIDEO_SEGMENT_EVIDENCE_INVALID%'; end;
 bad:=jsonb_set(assets,'{0,sha256}','"ABC"'); begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,bad); raise exception 'bad hash accepted'; exception when others then assert sqlerrm like '%VIDEO_SEGMENT_EVIDENCE_INVALID%'; end;
 bad:=jsonb_set(assets,'{0,object_key}',to_jsonb('creator-video-projects/'||v.id||'/segments/9/bad.mp4')); begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,bad); raise exception 'bad namespace accepted'; exception when others then assert sqlerrm like '%VIDEO_OBJECT_NAMESPACE_INVALID%'; end;
 bad:=jsonb_set(assets,'{1,bucket}','"other-bucket"'); begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,bad); raise exception 'mixed bucket accepted'; exception when others then assert sqlerrm like '%VIDEO_BUCKET_CONFLICT%'; end;
end$$;
