delete from public.video_project_segments where project_id=(select project_id from submitted) and ordinal=1;
do $$ declare v public.video_projects;a public.compute_job_attempts;assets jsonb;begin select * into v from public.video_projects where id=(select project_id from submitted);select * into a from public.compute_job_attempts where job_id=v.video_job_id;assets:=jsonb_build_array(jsonb_build_object('ordinal',0,'bucket','video-private','object_key','creator-video-projects/'||v.id||'/segments/0/segment-0.mp4','mime_type','video/mp4','size_bytes',1000,'sha256',repeat('1',64)),jsonb_build_object('ordinal',1,'bucket','video-private','object_key','creator-video-projects/'||v.id||'/segments/1/segment-1.mp4','mime_type','video/mp4','size_bytes',1001,'sha256',repeat('2',64)));begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,assets);raise exception 'missing segment repaired';exception when others then assert sqlerrm like '%VIDEO_FINALIZATION_REPLAY_CONFLICT%';end;assert not exists(select 1 from public.video_project_segments where project_id=v.id and ordinal=1);end$$;
insert into public.video_project_segments select * from saved_segment;
create temporary table saved_video_telemetry as select id,internal_telemetry from public.compute_job_attempts where job_id=(select video_job_id from public.video_projects where id=(select project_id from submitted));
update public.compute_job_attempts set internal_telemetry=internal_telemetry-'workload_finalization_fingerprint' where id=(select id from saved_video_telemetry);
do $$ declare v public.video_projects;a public.compute_job_attempts;assets jsonb;begin select * into v from public.video_projects where id=(select project_id from submitted);select * into a from public.compute_job_attempts where job_id=v.video_job_id;assets:=jsonb_build_array(jsonb_build_object('ordinal',0,'bucket','video-private','object_key','creator-video-projects/'||v.id||'/segments/0/segment-0.mp4','mime_type','video/mp4','size_bytes',1000,'sha256',repeat('1',64)),jsonb_build_object('ordinal',1,'bucket','video-private','object_key','creator-video-projects/'||v.id||'/segments/1/segment-1.mp4','mime_type','video/mp4','size_bytes',1001,'sha256',repeat('2',64)));begin perform public.finalize_video_compute_job(v.video_job_id,a.id,a.lease_token,assets);raise exception 'missing fingerprint repaired';exception when others then assert sqlerrm like '%VIDEO_FINALIZATION_REPLAY_CONFLICT%';end;assert a.internal_telemetry->>'workload_finalization_fingerprint' is null;end$$;
update public.compute_job_attempts a set internal_telemetry=s.internal_telemetry from saved_video_telemetry s where a.id=s.id;

create temporary table stitch_claim as select * from public.claim_compute_job('stitch','stitch-test');
update public.compute_jobs set state='running',started_at=clock_timestamp() where id=(select job_id from stitch_claim);
update public.compute_job_attempts set started_at=clock_timestamp(),provider_dispatch_intent_at=clock_timestamp(),provider_dispatched_at=clock_timestamp(),provider_operation_ref='opaque-stitch-operation',actual_cost_micros=0,runtime_ms=6000 where id=(select attempt_id from stitch_claim);
do $$ declare c record;e jsonb;bad jsonb;begin select * into c from stitch_claim;e:=jsonb_build_object('asset',jsonb_build_object('bucket','video-private','object_key','creator-video-projects/'||(select project_id from submitted)||'/final/final.mp4','mime_type','video/mp4','size_bytes',2000,'sha256',repeat('3',64)),'duration_ms',10000,'width',1920,'height',1080,'fps_millihz',30000);
 assert (public.stitch_compute_manifest(c.job_id,c.attempt_id,c.lease_token)->>'project_id')=(select project_id::text from submitted);
 begin perform public.stitch_compute_manifest(c.job_id,c.attempt_id,gen_random_uuid());raise exception 'wrong Stitch manifest lease accepted';exception when others then assert sqlerrm like '%STITCH_MANIFEST_AUTHORITY_MISMATCH%';end;
 bad:=jsonb_set(e,'{duration_ms}','"10000"');begin perform public.finalize_stitch_compute_job(c.job_id,c.attempt_id,c.lease_token,bad);raise exception 'string duration accepted';exception when others then assert sqlerrm like '%STITCH_OUTPUT_INVALID%';end;
 bad:=jsonb_set(e,'{asset,size_bytes}','"2000"');begin perform public.finalize_stitch_compute_job(c.job_id,c.attempt_id,c.lease_token,bad);raise exception 'string size accepted';exception when others then assert sqlerrm like '%STITCH_OUTPUT_INVALID%';end;
 bad:=jsonb_set(e,'{height}','1079');begin perform public.finalize_stitch_compute_job(c.job_id,c.attempt_id,c.lease_token,bad);raise exception 'short edge accepted';exception when others then assert sqlerrm like '%STITCH_OUTPUT_INVALID%';end;
 bad:=jsonb_set(e,'{fps_millihz}','29899');begin perform public.finalize_stitch_compute_job(c.job_id,c.attempt_id,c.lease_token,bad);raise exception 'low fps accepted';exception when others then assert sqlerrm like '%STITCH_OUTPUT_INVALID%';end;
 bad:=jsonb_set(e,'{fps_millihz}','30101');begin perform public.finalize_stitch_compute_job(c.job_id,c.attempt_id,c.lease_token,bad);raise exception 'high fps accepted';exception when others then assert sqlerrm like '%STITCH_OUTPUT_INVALID%';end;
 bad:=jsonb_set(e,'{duration_ms}','16000');begin perform public.finalize_stitch_compute_job(c.job_id,c.attempt_id,c.lease_token,bad);raise exception 'duration accepted';exception when others then assert sqlerrm like '%STITCH_OUTPUT_INVALID%';end;
end$$;
select public.finalize_stitch_compute_job((select job_id from stitch_claim),(select attempt_id from stitch_claim),(select lease_token from stitch_claim),jsonb_build_object('asset',jsonb_build_object('bucket','video-private','object_key','creator-video-projects/'||(select project_id from submitted)||'/final/final.mp4','mime_type','video/mp4','size_bytes',2000,'sha256',repeat('3',64)),'duration_ms',10000,'width',1920,'height',1080,'fps_millihz',30000));
do $$ begin
 assert (select completed_at is not null from public.video_projects where id=(select project_id from submitted));
 assert (select count(*)=1 from public.generations where id=(select project_id from submitted) and job_type='video' and status='completed' and image_url is null and r2_bucket is null and r2_key is null and runpod_job_id is null);
