do $$ begin begin perform public.finalize_stitch_compute_job((select job_id from stitch_claim),(select attempt_id from stitch_claim),(select lease_token from stitch_claim),jsonb_build_object('asset',jsonb_build_object('bucket','video-private','object_key','creator-video-projects/'||(select project_id from submitted)||'/final/final.mp4','mime_type','video/mp4','size_bytes',2000,'sha256',repeat('3',64)),'duration_ms',10000,'width',1920,'height',1080,'fps_millihz',30000));raise exception 'poisoned generation repaired';exception when others then assert sqlerrm like '%VIDEO_GENERATION_CONFLICT%';end;assert (select body_type='poisoned' from public.generations where id=(select project_id from submitted));end$$;
