create temporary table saved_final_asset as select * from public.generation_assets where generation_id=(select project_id from submitted);
delete from public.generation_assets where generation_id=(select project_id from submitted);
do $$ begin begin perform public.finalize_stitch_compute_job((select job_id from stitch_claim),(select attempt_id from stitch_claim),(select lease_token from stitch_claim),jsonb_build_object('asset',jsonb_build_object('bucket','video-private','object_key','creator-video-projects/'||(select project_id from submitted)||'/final/final.mp4','mime_type','video/mp4','size_bytes',2000,'sha256',repeat('3',64)),'duration_ms',10000,'width',1920,'height',1080,'fps_millihz',30000));raise exception 'missing final asset repaired';exception when others then assert sqlerrm like '%STITCH_FINALIZATION_REPLAY_CONFLICT%';end;assert not exists(select 1 from public.generation_assets where generation_id=(select project_id from submitted));end$$;
insert into public.generation_assets select * from saved_final_asset;
create temporary table saved_stitch_telemetry as select id,internal_telemetry from public.compute_job_attempts where id=(select attempt_id from stitch_claim);
update public.compute_job_attempts set internal_telemetry=internal_telemetry-'workload_finalization_fingerprint' where id=(select id from saved_stitch_telemetry);
do $$ begin begin perform public.finalize_stitch_compute_job((select job_id from stitch_claim),(select attempt_id from stitch_claim),(select lease_token from stitch_claim),jsonb_build_object('asset',jsonb_build_object('bucket','video-private','object_key','creator-video-projects/'||(select project_id from submitted)||'/final/final.mp4','mime_type','video/mp4','size_bytes',2000,'sha256',repeat('3',64)),'duration_ms',10000,'width',1920,'height',1080,'fps_millihz',30000));raise exception 'missing Stitch fingerprint repaired';exception when others then assert sqlerrm like '%STITCH_FINALIZATION_REPLAY_CONFLICT%';end;assert (select internal_telemetry->>'workload_finalization_fingerprint' is null from public.compute_job_attempts where id=(select attempt_id from stitch_claim));end$$;
update public.compute_job_attempts a set internal_telemetry=s.internal_telemetry from saved_stitch_telemetry s where a.id=s.id;
create temporary table completed_replay as select * from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'video-project-a',repeat('a',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":10,"fps":30,"prompt":"test","body_type":"default"}','standard');
do $$ begin assert (select creator_status='completed' and not can_cancel from completed_replay);end$$;

-- Recovery manifests/finalizers preserve exact recovery authority, cost, and replay contracts.
create temporary table recovered_project as select project_id from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'recovered-project',repeat('b',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":10,"prompt":"recovered","body_type":"recovered-body"}','standard');
update public.compute_jobs set state='recovering',attempt_count=1 where id=(select video_job_id from public.video_projects where id=(select project_id from recovered_project));
insert into public.compute_job_attempts(job_id,ordinal,lease_token,worker_ref,lease_expires_at,started_at,provider_dispatch_intent_at,provider_dispatched_at,provider_operation_ref,actual_cost_micros,runtime_ms,recovery_token,recovery_lease_token,recovery_worker_ref,recovery_heartbeat_at,recovery_lease_expires_at)
 select video_job_id,1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','lost-video',clock_timestamp()-interval '1 minute',clock_timestamp(),clock_timestamp(),clock_timestamp(),'recovered-video-op',7,5000,'cccccccc-cccc-4ccc-8ccc-cccccccccccc','dddddddd-dddd-4ddd-8ddd-dddddddddddd','video-recovery',clock_timestamp(),clock_timestamp()+interval '5 minutes' from public.video_projects where id=(select project_id from recovered_project);
do $$ declare v public.video_projects;a public.compute_job_attempts;begin select * into v from public.video_projects where id=(select project_id from recovered_project);select * into a from public.compute_job_attempts where job_id=v.video_job_id;assert (public.recovered_video_compute_manifest(v.video_job_id,a.id,a.recovery_token,a.recovery_lease_token)->>'project_id')=v.id::text;begin perform public.recovered_video_compute_manifest(v.video_job_id,a.id,gen_random_uuid(),a.recovery_lease_token);raise exception 'wrong recovery token accepted';exception when others then assert sqlerrm like '%VIDEO_RECOVERY_AUTHORITY_MISMATCH%';end;end$$;
select public.finalize_recovered_video_compute_job(v.video_job_id,a.id,a.recovery_token,a.recovery_lease_token,jsonb_build_array(jsonb_build_object('ordinal',0,'bucket','video-recovered','object_key','creator-video-projects/'||v.id||'/segments/0/a.mp4','mime_type','video/mp4','size_bytes',1100,'sha256',repeat('4',64)),jsonb_build_object('ordinal',1,'bucket','video-recovered','object_key','creator-video-projects/'||v.id||'/segments/1/b.mp4','mime_type','video/mp4','size_bytes',1101,'sha256',repeat('5',64))),7,5000,'recovered-video-op') from public.video_projects v join public.compute_job_attempts a on a.job_id=v.video_job_id where v.id=(select project_id from recovered_project);
-- exact recovered Video replay
select public.finalize_recovered_video_compute_job(v.video_job_id,a.id,a.recovery_token,'dddddddd-dddd-4ddd-8ddd-dddddddddddd',jsonb_build_array(jsonb_build_object('ordinal',0,'bucket','video-recovered','object_key','creator-video-projects/'||v.id||'/segments/0/a.mp4','mime_type','video/mp4','size_bytes',1100,'sha256',repeat('4',64)),jsonb_build_object('ordinal',1,'bucket','video-recovered','object_key','creator-video-projects/'||v.id||'/segments/1/b.mp4','mime_type','video/mp4','size_bytes',1101,'sha256',repeat('5',64))),7,5000,'recovered-video-op') from public.video_projects v join public.compute_job_attempts a on a.job_id=v.video_job_id where v.id=(select project_id from recovered_project);
do $$ declare v public.video_projects;a public.compute_job_attempts;begin select * into v from public.video_projects where id=(select project_id from recovered_project);select * into a from public.compute_job_attempts where job_id=v.video_job_id;begin perform public.finalize_recovered_video_compute_job(v.video_job_id,a.id,a.recovery_token,'dddddddd-dddd-4ddd-8ddd-dddddddddddd',jsonb_build_array(jsonb_build_object('ordinal',0,'bucket','video-recovered','object_key','creator-video-projects/'||v.id||'/segments/0/a.mp4','mime_type','video/mp4','size_bytes',1100,'sha256',repeat('4',64)),jsonb_build_object('ordinal',1,'bucket','video-recovered','object_key','creator-video-projects/'||v.id||'/segments/1/b.mp4','mime_type','video/mp4','size_bytes',1101,'sha256',repeat('5',64))),8,5000,'recovered-video-op');raise exception 'recovery cost conflict accepted';exception when others then assert sqlerrm like '%VIDEO_FINALIZATION_REPLAY_CONFLICT%';end;end$$;
create temporary table recovered_stitch_claim as select * from public.claim_compute_job('stitch','lost-stitch');
update public.compute_jobs set state='recovering',lease_token=null,lease_expires_at=null where id=(select job_id from recovered_stitch_claim);
update public.compute_job_attempts set started_at=clock_timestamp(),provider_dispatch_intent_at=clock_timestamp(),provider_dispatched_at=clock_timestamp(),provider_operation_ref='recovered-stitch-op',actual_cost_micros=9,runtime_ms=6000,recovery_token='eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee',recovery_lease_token='ffffffff-ffff-4fff-8fff-ffffffffffff',recovery_worker_ref='stitch-recovery',recovery_heartbeat_at=clock_timestamp(),recovery_lease_expires_at=clock_timestamp()+interval '5 minutes' where id=(select attempt_id from recovered_stitch_claim);
do $$ begin assert (public.recovered_stitch_compute_manifest((select job_id from recovered_stitch_claim),(select attempt_id from recovered_stitch_claim),'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','ffffffff-ffff-4fff-8fff-ffffffffffff')->>'project_id')=(select project_id::text from recovered_project);begin perform public.recovered_stitch_compute_manifest((select job_id from recovered_stitch_claim),(select attempt_id from recovered_stitch_claim),gen_random_uuid(),'ffffffff-ffff-4fff-8fff-ffffffffffff');raise exception 'wrong Stitch recovery accepted';exception when others then assert sqlerrm like '%STITCH_RECOVERY_AUTHORITY_MISMATCH%';end;end$$;
select public.finalize_recovered_stitch_compute_job((select job_id from recovered_stitch_claim),(select attempt_id from recovered_stitch_claim),'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','ffffffff-ffff-4fff-8fff-ffffffffffff',jsonb_build_object('asset',jsonb_build_object('bucket','video-recovered','object_key','creator-video-projects/'||(select project_id from recovered_project)||'/final/final.mp4','mime_type','video/mp4','size_bytes',2100,'sha256',repeat('6',64)),'duration_ms',10000,'width',1920,'height',1080,'fps_millihz',30000),9,6000,'recovered-stitch-op');
-- exact recovered Stitch replay
select public.finalize_recovered_stitch_compute_job((select job_id from recovered_stitch_claim),(select attempt_id from recovered_stitch_claim),'eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','ffffffff-ffff-4fff-8fff-ffffffffffff',jsonb_build_object('asset',jsonb_build_object('bucket','video-recovered','object_key','creator-video-projects/'||(select project_id from recovered_project)||'/final/final.mp4','mime_type','video/mp4','size_bytes',2100,'sha256',repeat('6',64)),'duration_ms',10000,'width',1920,'height',1080,'fps_millihz',30000),9,6000,'recovered-stitch-op');

-- Status precedence and cancellation remain truthful and idempotent.
create temporary table failure_project as select project_id from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'failure-status',repeat('7',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":10}','standard');
update public.video_projects set cancellation_requested_at=clock_timestamp() where id=(select project_id from failure_project);
update public.compute_jobs set state='failed',terminal_at=clock_timestamp(),safe_error_code='TEST_FAILURE' where id=(select video_job_id from public.video_projects where id=(select project_id from failure_project));
do $$ begin assert (select creator_status='failed' from public.creator_video_project_status('10000000-0000-4000-8000-000000000001',(select project_id from failure_project)));assert (select state='failed' and safe_error_code='VIDEO_GENERATION_STAGE_FAILED' from public.compute_jobs where id=(select stitch_job_id from public.video_projects where id=(select project_id from failure_project)));end$$;
create temporary table cancel_project as select project_id from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'cancel-queued',repeat('8',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":10}','standard');
select public.cancel_video_project('10000000-0000-4000-8000-000000000001',(select project_id from cancel_project));
select public.cancel_video_project('10000000-0000-4000-8000-000000000001',(select project_id from cancel_project));
do $$ begin assert (select creator_status='cancelled' and not can_cancel from public.creator_video_project_status('10000000-0000-4000-8000-000000000001',(select project_id from cancel_project)));end$$;

-- Identical submission replays the same safe project; changed fingerprints conflict.
select project_id from public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'video-project-a',repeat('a',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":10,"fps":30,"prompt":"test","body_type":"default"}','standard');
do $$ begin begin perform public.submit_video_project_compute_jobs('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',null,'video-project-a',repeat('b',64),'{"identity_id":"20000000-0000-4000-8000-000000000001","mode":"text_to_video","requested_duration_seconds":10}','standard'); raise exception 'conflict accepted'; exception when others then assert sqlerrm like '%IDEMPOTENCY_CONFLICT%'; end; end$$;
